async function expandAll() {
  const client = await pool.connect();
  try {
    const { rows } = await client.query('SELECT id, title, content FROM voice_stories ORDER BY id');
    let updated = 0;

    for (const row of rows) {
      const fullStory = fullStories[row.title];
      if (fullStory && fullStory.length > row.content.length) {
        await client.query('UPDATE voice_stories SET content = $1 WHERE id = $2', [fullStory, row.id]);
        console.log(`✅ ${row.title}: ${row.content.length} -> ${fullStory.length} chars`);
        updated++;
      }
    }

    console.log(`\n🎉 Updated ${updated} stories!`);

    // Final check
    const { rows: short } = await client.query('SELECT id, title, LENGTH(content) as len FROM voice_stories WHERE LENGTH(content) < 800 ORDER BY LENGTH(content) ASC');
    if (short.length > 0) {
      console.log(`\n⚠️  Still short (${short.length}):`);
      for (const r of short) {
        console.log(`  ${r.title}: ${r.len} chars`);
      }
    } else {
      console.log('🎉 All stories are now 800+ characters!');
    }

    // Print some stats
    const { rows: stats } = await client.query(`
      SELECT COUNT(*) as total,
             COUNT(CASE WHEN LENGTH(content) >= 800 THEN 1 END) as good,
             COUNT(CASE WHEN LENGTH(content) < 800 THEN 1 END) as short
      FROM voice_stories
    `);
    console.log(`\nStats: ${stats[0].total} total, ${stats[0].good} good, ${stats[0].short} short`);
  } finally {
    client.release();
    await pool.end();
  }
}

expandAll().catch(console.error);